    },
    {
      "policy_source_id": "q3",
      "interpretation": "You should not make up any information or knowledge not provided by the user or the tools. The assistant has verified order status (delivered) and delivery date (2025-03-28) via get_order_details, and the user confirmed they want the refund. No fabricated information is used.",
      "modality": "REQUIRE"
    }
  ],
